DROP TABLE IF EXISTS procedimentos;
CREATE TABLE procedimentos (
  ip_cod CHAR(10),
  ip_dscr CHAR(150)
  );

DROP TABLE IF EXISTS cadgerrs;
CREATE TABLE cadgerrs (
  cnes CHAR(7),
  cpf_cnpj CHAR(14),
  fantasia CHAR(60),
  raz_soci CHAR(85),
  rsoc_man CHAR(60),
  logradou CHAR(40),
  num_end CHAR(10),
  compleme CHAR(20),
  bairro CHAR(20),
  cod_cep CHAR(8),
  telefone CHAR(13),
  fax CHAR(13),
  email CHAR(30),
  regsaude CHAR(4),
  micr_reg CHAR(6),
  distrsan CHAR(4),
  distradm CHAR(4),
  codufmun CHAR(6),
  excluido CHAR(1),
  dataincl DATE,
