DROP TABLE IF EXISTS cbo;

CREATE TABLE cbo (
  cbo CHAR(6),
  ds_cbo CHAR(150));

DROP TABLE IF EXISTS cid;

CREATE TABLE cid (
  cd_cod CHAR(4),
  opc CHAR(1),
  cat CHAR(1),
  subcat CHAR(1),
  cd_descr CHAR(50),
  restrsexo CHAR(1),
  campos_rad CHAR(3),
