  repete_rad CHAR(1));
DROP TABLE IF EXISTS tb_sigtaw;
CREATE TABLE tb_sigtaw (
  ip_cod CHAR(10),
  ip_dscr CHAR(150));

DROP TABLE IF EXISTS rl_municip_micibge;
CREATE TABLE rl_municip_micibge (
  co_municip NUMERIC(6),
  co_micibge NUMERIC(5));

DROP TABLE IF EXISTS tb_micibge;
CREATE TABLE tb_micibge (
  co_micibge NUMERIC(5),
  co_status CHAR(8),
  ds_nome CHAR(41),
  ds_nomepad CHAR(21),
  ds_abrev CHAR(21),
  ordem NUMERIC(1));

DROP TABLE IF EXISTS tb_municip;
CREATE TABLE tb_municip (
  co_municip CHAR(6),
  co_municdv CHAR(1),
  co_status CHAR(1),
  ds_nome CHAR(41),
  sg_uf CHAR(2),
